import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Arrays;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());}Arrays.sort(a);int moves = 0;boolean[] used = new boolean[n];int left = 0;for (int i = 0; i < n; i++) {if (used[i]) continue;moves++;used[i] = true;if (left <= i) left = i + 1;while (left < n && (a[left] - a[i] > 2)) {left++;}if (left < n) {used[left] = true;left++;}}System.out.println(moves);}}}